import {esc} from './organiser-utils.js';
export async function openInsights({sb,host,editor,status,isCurrent}){
 editor.replaceChildren();host.innerHTML='<section class="app-card"><p class="app-badge">VISITOR MEASUREMENT</p><h2>See what people use.</h2><p>Anonymous event totals from visitors who choose to allow measurement. These are not unique visitors or a complete picture of traffic. Refreshes count as another visit; blocked requests and browser exits may be missed.</p><label>Period<select id="insights-period"><option value="7">Last 7 days</option><option value="30" selected>Last 30 days</option><option value="90">Last 90 days</option></select></label><p>Dates use Indian Standard Time. No names, form contents or individual visitor trails are stored.</p><div id="insights-results" aria-live="polite"></div></section>';let version=0;
 async function draw(){const n=++version,days=Number(host.querySelector('select').value),start=new Date(Date.now()-(days-1)*86400000).toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});const rows=[];try{for(let offset=0;;offset+=500){const r=await sb.from('elan_visit_totals').select('*').gte('day',start).order('day',{ascending:false}).order('page').order('event').range(offset,offset+499);if(r.error)throw r.error;rows.push(...r.data);if(r.data.length<500)break;}if(n!==version||!isCurrent())return;const pages=new Map();for(const r of rows){const values=pages.get(r.page)||{};values[r.event]=(values[r.event]||0)+r.hits;pages.set(r.page,values);}host.querySelector('#insights-results').innerHTML=pages.size?'<div class="table-scroll"><table><thead><tr><th>Page</th><th>Views</th><th>30s engaged</th><th>Exit events</th><th>Forms started</th><th>Forms saved</th></tr></thead><tbody>'+[...pages].sort((a,b)=>(b[1].view||0)-(a[1].view||0)).map(([p,v])=>'<tr><th>'+esc(p.replaceAll('-',' '))+'</th>'+['view','engaged','exit','form_start','form_success'].map(k=>'<td>'+(v[k]||0)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p>Exit events mean a page was left; they do not tell us why. Form counts are per page visit, so they should not be treated as a person-level conversion funnel.</p>':'<p>No consenting visitor events in this period yet. Measurement is off by default; visitors can enable it in the footer.</p>';status('');}catch(e){status(e.message,true);}}
 host.querySelector('select').onchange=draw;await draw();
}
